CREATE TABLE IF NOT EXISTS install_request (request_id VARCHAR(20) PRIMARY KEY, app_id VARCHAR(20) NOT NULL, app_name VARCHAR(100) NOT NULL, app_description VARCHAR(1000) NOT NULL, app_url VARCHAR(255) NULL, developer_type VARCHAR(11) NOT NULL, user_id VARCHAR(20) NOT NULL, team_id VARCHAR(20) NULL, enterprise_id VARCHAR(20) NULL, message VARCHAR(1000) NULL, is_user_app_collaborator BOOLEAN NOT NULL, requested_at BIGINT NOT NULL, user_verified BOOLEAN NOT NULL, automatic_decision VARCHAR(14) NOT NULL, automatic_decision_reason VARCHAR(30) NULL, status VARCHAR(14) NOT NULL, resolved_by VARCHAR(20) NULL, resolved_at TIMESTAMP NULL, resolution_message VARCHAR(2000) NULL, resolution VARCHAR(10) NULL, review_message_ts VARCHAR(30) NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE INDEX install_request_app_id ON install_request (app_id);
CREATE INDEX install_request_user_id ON install_request (user_id);
CREATE INDEX install_request_status ON install_request (status);